namespace LakeSkin {
public class Theme {
 public int Version {get;set;} public string Name {get;set;} public string Accent {get;set;} public string Background {get;set;} public bool Icons {get;set;}
 public Theme(){Version=1;Name="玫瑰粉";Accent="#CD4880";Background="default";Icons=true;}
 public Theme Clone(){return new Theme{Version=Version,Name=Name,Accent=Accent,Background=Background,Icons=Icons};}
 public void Validate(){if(Version!=1)throw new Exception("不支持这个主题文件版本。");if(String.IsNullOrWhiteSpace(Name)||Name.Length>40)throw new Exception("主题名称需为 1–40 个字符。");ColorValue(Accent);if(Background!="default")ColorValue(Background);}
 public static Color ColorValue(string s){if(s==null||!System.Text.RegularExpressions.Regex.IsMatch(s,"^#[0-9a-fA-F]{6}$"))throw new Exception("颜色格式应为 #RRGGBB，例如 #CD4880。");return ColorTranslator.FromHtml(s);}
}
public static class Storage {
 public static string Root=AppDomain.CurrentDomain.BaseDirectory;
 public static string Engine=Path.Combine(Root,"engine");
 public static JavaScriptSerializer Json=new JavaScriptSerializer();
 public static void Write(string path,string data){Directory.CreateDirectory(Path.GetDirectoryName(path));string tmp=path+".tmp";File.WriteAllText(tmp,data,new System.Text.UTF8Encoding(false));if(File.Exists(path))File.Replace(tmp,path,null);else File.Move(tmp,path);}
 public static Theme Read(string path){if(new FileInfo(path).Length>65536)throw new Exception("主题文件过大。");Theme t=Json.Deserialize<Theme>(File.ReadAllText(path));if(t==null)throw new Exception("主题文件为空。");t.Validate();return t;}
 public static string Qss(Theme t){t.Validate();Color c=Theme.ColorValue(t.Accent);string pale=ColorTranslator.ToHtml(Color.FromArgb((c.R+255*8)/9,(c.G+255*8)/9,(c.B+255*8)/9));string fg=(.2126*c.R+.7152*c.G+.0722*c.B)>160?"#20242c":"#ffffff";return "/* LakeSkin: generated theme */\nQWidget { selection-background-color:"+t.Accent+"; selection-color:"+fg+"; }\nQMenu::item:selected, QAbstractItemView::item:selected {background:"+t.Accent+";color:"+fg+";}\nQPushButton:hover {background:"+pale+";}\n"+(t.Background=="default"?"":"QWidget {background-color:"+t.Background+";color:"+((.2126*Theme.ColorValue(t.Background).R+.7152*Theme.ColorValue(t.Background).G+.0722*Theme.ColorValue(t.Background).B)<128?"#F3F4F6":"#272B34")+";}\n");}
 public static void Prepare(Theme t){t.Validate();Write(Path.Combine(Engine,"theme.qss"),Qss(t));Write(Path.Combine(Engine,"theme.cfg"),t.Accent.Substring(1)+" "+(t.Icons?"1":"0"));Write(Path.Combine(Root,"themes","last-theme.json"),Json.Serialize(t));}
 public static void Log(string message){try{Directory.CreateDirectory(Path.Combine(Root,"data"));File.AppendAllText(Path.Combine(Root,"data","activity.log"),DateTime.Now.ToString("s")+" "+message+Environment.NewLine);}catch{}}
}
public class PaletteButton:Button {
 public Color Swatch {get;set;} public bool Chosen;
 public PaletteButton(string name,Color c){Text=name;Swatch=c;Size=new Size(80,62);FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;BackColor=Color.White;Cursor=Cursors.Hand;Margin=new Padding(0,0,8,8);}
 protected override void OnPaint(PaintEventArgs e){e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;e.Graphics.Clear(Chosen?Color.FromArgb(242,240,248):Color.White);using(SolidBrush b=new SolidBrush(Swatch))e.Graphics.FillEllipse(b,30,8,20,20);TextRenderer.DrawText(e.Graphics,Text,Font,new Rectangle(0,34,Width,22),Color.FromArgb(48,52,65),TextFormatFlags.HorizontalCenter);if(Chosen)using(Pen p=new Pen(Swatch,2))e.Graphics.DrawRectangle(p,1,1,Width-3,Height-3);}
}
