 Button Btn(string text,int width){return new Button{Text=text,Width=width,Height=34,FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(247,248,250),ForeColor=Color.FromArgb(55,61,76),Cursor=Cursors.Hand,FlatAppearance={BorderColor=Color.FromArgb(225,228,234)}};}
