 void LoadFields(){loading=true;accent.Text=theme.Accent;name.Text=theme.Name;icons.Checked=theme.Icons;backgrounds.SelectedIndex=theme.Background=="default"?0:theme.Background.ToLower()=="#ffffff"?1:2;bgHex.Text=theme.Background=="default"?"#FFFFFF":theme.Background;bgHex.Enabled=backgrounds.SelectedIndex==2;loading=false;UpdateTheme();}
 void UpdateTheme(){if(loading)return;try{Theme.ColorValue(accent.Text.Trim());if(backgrounds.SelectedIndex==2)Theme.ColorValue(bgHex.Text.Trim());theme.Accent=accent.Text.Trim().ToUpper();theme.Background=backgrounds.SelectedIndex==0?"default":backgrounds.SelectedIndex==1?"#FFFFFF":bgHex.Text.Trim().ToUpper();theme.Icons=icons.Checked;accent.BackColor=Color.White;bgHex.BackColor=Color.White;preview.Current=theme.Clone();preview.Invalidate();foreach(var b in swatches){b.Chosen=b.Swatch.ToArgb()==Theme.ColorValue(theme.Accent).ToArgb();b.Invalidate();}}catch{accent.BackColor=Color.FromArgb(255,238,238);}}
 void PickColor(bool bg){using(ColorDialog d=new ColorDialog{FullOpen=true}){try{d.Color=Theme.ColorValue(bg?bgHex.Text:accent.Text);}catch{}if(d.ShowDialog(this)==DialogResult.OK){string hex=ColorTranslator.ToHtml(Color.FromArgb(d.Color.R,d.Color.G,d.Color.B));hex="#"+d.Color.R.ToString("X2")+d.Color.G.ToString("X2")+d.Color.B.ToString("X2");if(bg){backgrounds.SelectedIndex=2;bgHex.Text=hex;}else{accent.Text=hex;name.Text="自定义配色";}}}}
 Theme ReadFields(){Theme.ColorValue(accent.Text.Trim());if(backgrounds.SelectedIndex==2)Theme.ColorValue(bgHex.Text.Trim());UpdateTheme();theme.Name=name.Text.Trim();theme.Validate();return theme.Clone();}
 void Error(string msg){MessageBox.Show(this,msg,"湖畔换肤",MessageBoxButtons.OK,MessageBoxIcon.Information);}
 void SaveTheme(){try{Theme t=ReadFields();string path=Path.Combine(Storage.Root,"themes","theme-"+Guid.NewGuid().ToString("N")+".json");Storage.Write(path,Storage.Json.Serialize(t));RefreshSaved();hint.Text="主题已保存到我的主题";}catch(Exception ex){Error(ex.Message);}}
 void RefreshSaved(){loading=true;saved.Items.Clear();themeFiles.Clear();Directory.CreateDirectory(Path.Combine(Storage.Root,"themes"));foreach(string path in Directory.GetFiles(Path.Combine(Storage.Root,"themes"),"*.json")){if(Path.GetFileName(path)=="last-theme.json")continue;try{Theme t=Storage.Read(path);themeFiles.Add(path);saved.Items.Add(t.Name);}catch{}}loading=false;}
 void Import(){using(OpenFileDialog f=new OpenFileDialog{Filter="LakeSkin 主题|*.json"})if(f.ShowDialog(this)==DialogResult.OK){try{theme=Storage.Read(f.FileName);LoadFields();SaveTheme();}catch(Exception ex){Error(ex.Message);}}}
 void Export(){try{Theme t=ReadFields();using(SaveFileDialog f=new SaveFileDialog{Filter="LakeSkin 主题|*.json",FileName="LakeSkin-theme.json"})if(f.ShowDialog(this)==DialogResult.OK)Storage.Write(f.FileName,Storage.Json.Serialize(t));}catch(Exception ex){Error(ex.Message);}}
 void RefreshStatus(){try{var ps=Process.GetProcessesByName("westlake");status.Text=ps.Length==0?"○  i西湖 未运行":ps.Length==1?"●  i西湖 已运行":"检测到多个客户端";if(hint.Text.Length==0)hint.Text="只在点击应用后改变客户端外观";foreach(var p in ps)p.Dispose();}catch{status.Text="无法读取客户端状态";}}
 async Task Run(bool reset){if(busy)return;Theme t;try{t=ReadFields();}catch(Exception ex){if(!reset){Error(ex.Message);return;}t=new Theme();}string path=clientPath.Text.Trim();if(!reset&&(!File.Exists(path)||Path.GetFileName(path).ToLowerInvariant()!="westlake.exe")){Error("请选择已安装的 westlake.exe。");return;}busy=true;apply.Enabled=restore.Enabled=false;status.Text=reset?"正在恢复默认…":"正在应用配色…";try{int code=await Task.Run(()=>{Process[] ps=Process.GetProcessesByName("westlake");if(ps.Length==0&&reset)return 0;if(ps.Length==0){Process.Start(new ProcessStartInfo(path){WorkingDirectory=Path.GetDirectoryName(path)});for(int i=0;i<30;i++){Thread.Sleep(500);ps=Process.GetProcessesByName("westlake");if(ps.Length==1){try{bool ready=false;foreach(ProcessModule m in ps[0].Modules)if(m.ModuleName.Equals("Qt5Widgets.dll",StringComparison.OrdinalIgnoreCase))ready=true;if(ready)break;}catch{}}foreach(var p in ps)p.Dispose();ps=new Process[0];}}
 if(ps.Length!=1)throw new Exception("未找到唯一的 i西湖 进程，请打开客户端后重试。");int pid=ps[0].Id;ps[0].Dispose();if(!reset)Storage.Prepare(t);var info=new ProcessStartInfo(Path.Combine(Storage.Engine,"theme-helper.exe"),pid+" "+(reset?"restore":"apply")){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(Process p=Process.Start(info)){if(!p.WaitForExit(20000))throw new Exception("应用请求超时；请先退出 i西湖 再重新打开，不要反复点击应用。");string result=p.StandardOutput.ReadToEnd()+p.StandardError.ReadToEnd();Storage.Log((reset?"restore":"apply "+t.Accent)+" result="+p.ExitCode+" "+result.Trim());return p.ExitCode;}});
 if(code!=0)throw new Exception(CodeMessage(code));status.Text=reset?"✓  已请求恢复默认":"✓  已应用 "+t.Name;hint.Text=reset?"换色已关闭；必要时重新打开当前页面":"部分第三方页面和 Logo 可能保持原色";}
 catch(Exception ex){status.Text="未能完成应用";hint.Text="请查看提示后重试";Storage.Log("error "+ex.Message);Error(ex.Message);}finally{busy=false;apply.Enabled=restore.Enabled=true;}}
 public static string CodeMessage(int c){switch(c){case 2:return "没有操作客户端的权限。请让本工具与 i西湖 使用相同权限运行。";case 30:return "客户端 Qt 版本不匹配。目前仅适配 Qt 5.15.18，不会继续加载。";case 32:return "客户端已加载另一份 LakeSkin。请完整退出 i西湖，再使用当前目录的软件。";case 31:return "检测到之前的换肤模块。请完整退出 i西湖，再打开并使用本工具。";case 4:return "客户端还未准备好，请稍等后重试。";case 21:return "图标资源缺失或不匹配。请重新解压完整软件包。";case 22:return "已有应用请求正在执行，请稍后重试。";default:return "换肤未完成，错误码 "+c+"。请查看 data/activity.log。";}}
}
static class Program {
 [STAThread] static int Main(string[] args){bool created;using(Mutex mutex=new Mutex(true,"Local\\LakeSkin-ThemeStudio",out created)){if(!created){MessageBox.Show("湖畔换肤已经打开。","LakeSkin");return 0;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{if(args.Length>0&&args[0]=="--self-test"){Theme t=new Theme();t.Validate();if(!Storage.Qss(t).Contains("#CD4880"))throw new Exception("QSS color");if(Storage.Qss(t).Contains("QWidget {background-color"))throw new Exception("Default background changed");bool rejected=false;try{Theme.ColorValue("red;bad");}catch{rejected=true;}if(!rejected)throw new Exception("Color validation");string json=Storage.Json.Serialize(t);Theme round=Storage.Json.Deserialize<Theme>(json);round.Validate();if(round.Accent!=t.Accent||!round.Icons)throw new Exception("Roundtrip");t.Background="#FFFFFF";if(!Storage.Qss(t).Contains("background-color:#FFFFFF"))throw new Exception("Custom background");File.WriteAllText(Path.Combine(Storage.Root,"self-test.txt"),"PASS: defaults, accent QSS, custom background, invalid color rejection, JSON roundtrip");return 0;}MainWindow f=new MainWindow();if(args.Length==2&&args[0]=="--render"){f.Show();Application.DoEvents();using(Bitmap bmp=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bmp,new Rectangle(0,0,bmp.Width,bmp.Height));bmp.Save(args[1]);}f.Close();return 0;}Application.Run(f);return 0;}catch(Exception ex){Storage.Log(ex.ToString());MessageBox.Show(ex.Message,"LakeSkin");return 1;}}}
}
}
